def maximumCost(n, highways, k):
    # A trip of k highways visits k+1 distinct cities
    if k + 1 > n:
        return -1

    # Build adjacency list: city -> [(neighbor, cost)]
    adj = [[] for _ in range(n)]
    for a, b, cost in highways:
        adj[a].append((b, cost))
        adj[b].append((a, cost))  # Highways are bidirectional

    # dp[mask][u] = max cost of a path visiting exactly the cities in mask and ending at u (-1 = unreachable)
    dp = [[-1] * n for _ in range(1 << n)]
    for city in range(n):
        dp[1 << city][city] = 0

    ans = -1
    # new_mask > mask always, so increasing mask order is a valid topological order
    for mask in range(1 << n):
        bits = bin(mask).count('1')
        if bits > k + 1:
            continue
        for u in range(n):
            cur = dp[mask][u]
            if cur < 0:
                continue
            if bits == k + 1:
                # Exactly k highways used
                ans = max(ans, cur)
                continue
            for v, cost in adj[u]:
                if not (mask >> v) & 1:
                    nm = mask | (1 << v)
                    if dp[nm][v] < cur + cost:
                        dp[nm][v] = cur + cost

    return ans
